/// The desktop's themes, Main first (its case is aura, the saved name): Ghost's own, then one per
/// supported agent.
public enum ThemeID: String, CaseIterable, Sendable {
    case aura
    case claude
    case codex
    case grok
    case pi
    case antigravity
    case cursor
    case opencode
    case ohMyPi = "oh_my_pi"
    case hermes

    /// The name Settings shows.
    public var name: String {
        switch self {
        case .aura: "Main"
        case .claude: "Claude Code"
        case .codex: "Codex"
        case .grok: "Grok Build"
        case .pi: "Pi"
        case .antigravity: "Antigravity"
        case .cursor: "Cursor"
        case .opencode: "OpenCode"
        case .ohMyPi: "oh-my-pi"
        case .hermes: "Hermes"
        }
    }

    /// The agent whose mark Settings shows beside the theme; Main shows Ghost's own wing.
    public var agent: String? {
        switch self {
        case .aura: nil
        case .claude: "claude"
        case .codex: "codex"
        case .grok: "grok"
        case .pi: "pi"
        case .antigravity: "antigravity"
        case .cursor: "cursor"
        case .opencode: "opencode"
        case .ohMyPi: "oh-my-pi"
        case .hermes: "hermes"
        }
    }
}

/// Every colour the app takes from a theme in one appearance, as the desktop's `--g-*` tokens
/// resolve there.
public struct Palette: Sendable, Hashable {
    /// The theme this palette belongs to.
    public let theme: ThemeID
    /// Whether this is the dark appearance.
    public let isDark: Bool
    /// The opaque window under everything (`--g-window`).
    public let window: RGBA
    /// The page (`--g-bg`).
    public let page: RGBA
    /// The solid pane content sits on (`--g-glass-layer`).
    public let pane: RGBA
    /// A raised layer on the pane: the composer, cards (`--g-glass-pop`).
    public let raised: RGBA
    /// Surface 1 (`--g-surface-1`); in dark each surface is lighter.
    public let surface1: RGBA
    /// Surface 2 (`--g-surface-2`).
    public let surface2: RGBA
    /// Surface 3 (`--g-surface-3`), the agent tile.
    public let surface3: RGBA
    /// Surface 4 (`--g-surface-4`).
    public let surface4: RGBA
    /// Menus and popovers, which are solid (`--g-overlay`).
    public let overlay: RGBA
    /// The plate under the agents' white marks, dark in both appearances (`--g-brand-plate`).
    public let brandPlate: RGBA
    /// The faintest divider (`--g-line-faint`).
    public let lineFaint: RGBA
    /// An ordinary divider (`--g-line`).
    public let line: RGBA
    /// A strong line: control outlines and the agent tile's ring (`--g-line-strong`).
    public let lineStrong: RGBA
    /// Primary text (`--g-fg-1`).
    public let fg1: RGBA
    /// Secondary text (`--g-fg-2`).
    public let fg2: RGBA
    /// Tertiary text and meta lines (`--g-fg-3`).
    public let fg3: RGBA
    /// Disabled text (`--g-fg-4`).
    public let fg4: RGBA
    /// A filled control at rest (`--g-primary`).
    public let primary: RGBA
    /// A filled control under the pointer (`--g-primary-hover`).
    public let primaryHover: RGBA
    /// A filled control while pressed (`--g-primary-active`).
    public let primaryPressed: RGBA
    /// The label on a filled control (`--g-on-light`).
    public let onPrimary: RGBA
    /// A filled control that cannot act yet (`--g-fill-primary-disabled`).
    public let primaryDisabled: RGBA
    /// The theme's accent, volt: attention and focus (`--g-volt`).
    public let accent: RGBA
    /// A faint wash of the accent (`--g-volt-tint`).
    public let accentTint: RGBA
    /// Focus rings (`--g-focus`).
    public let focus: RGBA
    /// Selected text and rows (`--g-selection`).
    public let selection: RGBA
    /// A solid row under the pointer (`--g-hover`).
    public let hover: RGBA
    /// A solid selected row (`--g-selected`).
    public let selected: RGBA
    /// Success. The same in every theme (`--g-green`).
    public let green: RGBA
    /// A success card's fill (`--g-green-tint`).
    public let greenTint: RGBA
    /// Failure and destructive actions (`--g-red`).
    public let red: RGBA
    /// A destructive control under the pointer (`--g-red-hover`).
    public let redHover: RGBA
    /// An error card's fill (`--g-red-tint`).
    public let redTint: RGBA
    /// Caution: away, waiting (`--g-warning`).
    public let amber: RGBA
    /// A caution card's fill (`--g-warning-tint`).
    public let amberTint: RGBA
    /// The label on a red fill (`--g-on-danger`).
    public let onDanger: RGBA
    /// Ink ladder: a card's faint fill (`--g-glass-card`).
    public let inkCard: RGBA
    /// Ink ladder: a quiet control (`--g-glass-control`).
    public let inkControl: RGBA
    /// Ink ladder: a selected item (`--g-glass-selected`).
    public let inkSelected: RGBA
    /// Ink ladder: a control under the pointer (`--g-glass-control-hover`).
    public let inkHover: RGBA
    /// Ink ladder: a pressed control (`--g-glass-control-active`).
    public let inkActive: RGBA
    /// Ink ladder: a layer's hairline rim (`--g-glass-rim`).
    public let rim: RGBA
    /// Ink ladder: a stronger rim, as on focus (`--g-glass-rim-strong`).
    public let rimStrong: RGBA
    /// The sent message's bubble: fg-1 mixed into the pane, 10% in dark and 7% in light.
    public let paper: RGBA
    /// The words on the paper: fg-1 in both appearances.
    public let onPaper: RGBA
    /// Behind code blocks (`--g-code-bg`).
    public let codeBackground: RGBA
    /// Code's own text, between fg-1 and fg-2 (`--g-code-fg`).
    public let codeText: RGBA
    /// highlight.js keyword, selector-tag, built_in, doctag, template-tag and type (`--g-code-keyword`).
    public let syntaxKeyword: RGBA
    /// highlight.js string, regexp, template-variable, symbol, link, selector-attr and selector-pseudo (`--g-code-string`).
    public let syntaxString: RGBA
    /// highlight.js number, literal and bullet (`--g-code-number`).
    public let syntaxNumber: RGBA
    /// highlight.js title, section, selector-id, selector-class and name (`--g-code-function`).
    public let syntaxTitle: RGBA
    /// highlight.js attr, attribute, property, params and variable (`--g-code-bright`).
    public let syntaxAttr: RGBA
    /// highlight.js comment, quote and meta (`--g-code-dim`).
    public let syntaxComment: RGBA
    /// highlight.js addition (`--g-green`).
    public let syntaxAddition: RGBA
    /// highlight.js deletion (`--g-red-hover`).
    public let syntaxDeletion: RGBA
    /// Behind terminal output (`--g-terminal-bg`).
    public let terminalBackground: RGBA
    /// Terminal text (`--g-terminal-fg`).
    public let terminalText: RGBA
    /// The terminal's cursor (`--g-terminal-cursor`).
    public let terminalCursor: RGBA
    /// Text under the terminal's cursor (`--g-terminal-cursor-text`).
    public let terminalCursorText: RGBA
    /// Selected terminal text (`--g-terminal-selection`).
    public let terminalSelection: RGBA
    /// A diff's hunk header band (`--g-diff-hunk`).
    public let diffHunk: RGBA
    /// An added line (`--g-diff-add-line`).
    public let diffAddLine: RGBA
    /// The changed words on an added line (`--g-diff-add-word`).
    public let diffAddWord: RGBA
    /// A removed line (`--g-diff-del-line`).
    public let diffDeleteLine: RGBA
    /// The changed words on a removed line (`--g-diff-del-word`).
    public let diffDeleteWord: RGBA
    /// Behind a modal (`--g-scrim`).
    public let scrim: RGBA
    /// The terminal's sixteen ANSI colours, in SGR order: black, red, green, yellow, blue,
    /// magenta, cyan and white, then their bright forms (`--g-ansi-*`).
    public let ansi: [RGBA]
}

